import{_ as s,o as e,c as a,a3 as n}from"./chunks/framework.DhF4LrUq.js";const g=JSON.parse('{"title":"Configure SSO (OIDC and SAML)","description":"Configure SSO - connect your corporate OIDC or SAML identity provider to the organization so console users sign in through it.","frontmatter":{"description":"Configure SSO - connect your corporate OIDC or SAML identity provider to the organization so console users sign in through it."},"headers":[],"relativePath":"how-to/console/sso-oidc-saml.md","filePath":"how-to/console/sso-oidc-saml.md"}'),t={name:"how-to/console/sso-oidc-saml.md"};function o(r,i,l,p,h,d){return e(),a("div",null,[...i[0]||(i[0]=[n(`<h1 id="configure-sso-oidc-and-saml" tabindex="-1">Configure SSO (OIDC and SAML) <a class="header-anchor" href="#configure-sso-oidc-and-saml" aria-label="Permalink to &quot;Configure SSO (OIDC and SAML)&quot;">​</a></h1><p>Single sign-on puts your corporate identity provider in front of the Console: users click <strong>Continue with SSO</strong>, your provider (Google Workspace, Entra ID, Okta) authenticates them, and ShipperDog admits the session. Configuration is one typed record per provider kind — written by an Organization Administrator through the organization API.</p><p>How the flows work — authorization codes, tokens, sessions — is covered in <a href="/shipperdog/snapshot/concepts/identity-sso">identity and SSO</a>.</p><div class="tip custom-block"><p class="custom-block-title">Break-glass stays local</p><p>Platform administrators never authenticate through an organization&#39;s provider — their email-and-password login remains the break-glass path regardless of this configuration.</p></div><h2 id="configure-oidc" tabindex="-1">Configure OIDC <a class="header-anchor" href="#configure-oidc" aria-label="Permalink to &quot;Configure OIDC&quot;">​</a></h2><ol><li><p>Prepare the provider: create an application in your IdP with authorization-code flow. Note the <strong>issuer URL</strong>, the <strong>client ID</strong>, and a <strong>client secret</strong>.</p></li><li><p>Write the organization&#39;s IdP configuration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SHIPPERDOG_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/organizations/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ORG_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/idp-config&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ORG_ADMIN_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;providerType&quot;: &quot;OIDC&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;issuerUrl&quot;: &quot;https://login.example.com/realms/northwind&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;clientId&quot;: &quot;shipperdog-console&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;clientSecret&quot;: &quot;…&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;provisioningMode&quot;: &quot;INVITED_ONLY&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;enabled&quot;: true</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      }&#39;</span></span></code></pre></div></li><li><p>Choose the provisioning posture deliberately:</p><ul><li><strong><code>INVITED_ONLY</code></strong> (default) — only existing members can sign in through SSO; nobody is created.</li><li><strong><code>JIT</code></strong> — first sign-in provisions a password-less account with <code>jitDefaultRole</code> (default <code>VIEWER</code>, the least-privilege floor) and admits existing non-members.</li></ul></li><li><p>Optional hardening fields: <code>requireVerifiedEmail</code> (strict by default), <code>groupClaimName</code> + <code>roleMappings</code> (a group claim value maps to an organization role, applied on every login — the most privileged mapped group wins), <code>inactiveClaimName</code>.</p></li></ol><p>The secret is stored once through the platform&#39;s secret store; only an opaque reference is ever echoed again, and rotation discards the replaced material. <code>enabled: false</code> (the default) keeps SSO off until the record says otherwise — configure first, enable when tested.</p><h2 id="configure-saml" tabindex="-1">Configure SAML <a class="header-anchor" href="#configure-saml" aria-label="Permalink to &quot;Configure SAML&quot;">​</a></h2><p>SAML 2.0 rides the same route with <code>providerType: &quot;SAML&quot;</code>:</p><ol><li><p>Download your IdP&#39;s <strong>metadata XML</strong> (the EntityDescriptor).</p></li><li><p>Exchange service-provider metadata: your SP metadata document lives at <code>GET /api/v1/auth/sso/saml/{organizationId}/metadata</code> — register its entityID and its AssertionConsumerService URL with the IdP.</p></li><li><p>Write the configuration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SHIPPERDOG_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/organizations/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ORG_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/idp-config&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ORG_ADMIN_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;providerType&quot;: &quot;SAML&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;idpMetadataXml&quot;: &quot;&lt;EntityDescriptor&gt;…&lt;/EntityDescriptor&gt;&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;wantAssertionsSigned&quot;: true,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;provisioningMode&quot;: &quot;INVITED_ONLY&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;enabled&quot;: true</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      }&#39;</span></span></code></pre></div><p>Signature policy: <code>wantAssertionsSigned</code> (default true — Entra&#39;s shape) and <code>wantResponseSigned</code> (default false — Google Workspace signs the Response only; set this true and assertions false). At least one must be required. The read echoes the pinned certificates&#39; SHA-256 fingerprints — never the metadata XML.</p></li></ol><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><p>On the login page: enter the <strong>Organization ID (single sign-on)</strong> and click <strong>Continue with SSO</strong>. The configured provider kind dispatches; the provider&#39;s redirect lands back in the Console with a session. SSO sessions <em>are</em> local sessions — same claims, same revocation surfaces.</p><div class="tip custom-block"><p class="custom-block-title">IdP-initiated logout</p><p>The OIDC Back-Channel Logout endpoint revokes the linked account&#39;s refresh families when the IdP says the session ended — IdP-initiated logout and IdP session expiry land on the same leg.</p></div><h2 id="linking-and-provisioning" tabindex="-1">Linking and provisioning <a class="header-anchor" href="#linking-and-provisioning" aria-label="Permalink to &quot;Linking and provisioning&quot;">​</a></h2><p>Once a user has signed in through the provider, their account is linked to that provider subject permanently — logins resolve through the subject and never re-derive the account from email. Unlinked first-timers match by email (refused when the email is unverified under the strict default). For full lifecycle automation — joins, moves, leavers — add <a href="/shipperdog/snapshot/how-to/console/scim-provisioning">SCIM provisioning</a> on top.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/scim-provisioning">SCIM provisioning</a> · <a href="/shipperdog/snapshot/concepts/identity-sso">identity and SSO concepts</a> · <a href="/shipperdog/snapshot/roles/org-admin">org-admin quickstart</a></p>`,16)])])}const k=s(t,[["render",o]]);export{g as __pageData,k as default};
